        CultEvent.Random("am04", StatId.Authority, new Question("경쟁 교단의 지도자가 무릎 꿇고 합병을 청하러 왔습니다. 그의 뒤로 신도들이 불안하게 웅성입니다.\u001FThe leader of a rival cult has come on his knees to ask for a merger. Behind him, his followers murmur uneasily.",
