        CultEvent.Negative("ea40", c => GameSession.God.Pressure.Stage(Pressure.Earth, c) >= 5, new Question("당신을 체포하라는 영장이 발부되었다는 소문이 돕니다. 측근들이 도피를 권합니다.\u001FRumor says a warrant has been issued for your arrest. Your inner circle urges you to flee.",
