        CultEvent.Random("vs03", StatId.Communion, new Question("숙주의 영혼이 꿈속에서 당신에게 말을 겁니다. 그는 자신의 몸을 돌려 달라고 애원합니다.\u001FThe host's soul speaks to you in a dream. He begs you to give his body back.",
