        CultEvent.Random("vs23", StatId.Communion, new Question("깊은 접신 중 숙주의 입에서 아무도 모르는 고대어가 흘러나옵니다. 받아 적던 신도의 손이 멈춥니다.\u001FIn deep Communion, an ancient tongue no one knows pours from the host's mouth. The follower taking it down stops writing.",
                new Choice("고대어를 새 경전으로 엮는다\u001FCompile the ancient tongue into a new scripture", 0.70f, new Outcome("아무도 읽지 못하는 경전이 오히려 신성하게 여겨집니다.\u001FA scripture no one can read is revered as all the more sacred.").C(StatId.Doctrine, 20).C(StatId.Communion, 1),
                    new Outcome("받아 적은 내용이 뒤죽박죽입니다.\u001FWhat you transcribed is a jumble.").C(StatId.Doctrine, 3).P(PersonalStatId.Mentality, -2)).With(PersonalStatId.Mentality),
