        CultEvent.Random("vs24", StatId.Communion, new Question("숙주의 그림자가 당신의 움직임을 한 박자 늦게 따라옵니다. 그림자는 숙주의 영혼처럼 고개를 숙이고 있습니다.\u001FThe host's shadow follows your movements a beat late. It hangs its head like the host's soul.",
