                new Choice("그림자를 의식에 참여시킨다\u001FBring the shadow into the rite", 0.50f, new Outcome("신도들은 두 개의 형상을 가진 신을 보았다고 증언합니다.\u001FFollowers testify they saw a god with two forms.").C(StatId.FollowerFaith, 15).C(StatId.Communion, 2).X(GodEventEffect.Suspicion, 5),
                    new Outcome("그림자가 의식을 망쳐 버립니다.\u001FThe shadow ruins the rite.").P(PersonalStatId.Mentality, -3).X(GodEventEffect.Suspicion, 5)).With(PersonalStatId.Mentality))),
        CultEvent.Random("vs25", StatId.Communion, new Question("숙주의 몸이 쾌락에 너무 익숙해져 이제는 웬만한 향락으로는 회복되지 않습니다. 몸이 더 강한 자극을 원합니다.\u001FThe host's body has grown so used to pleasure that ordinary indulgence no longer restores it. It craves something stronger.",
