                    new Outcome("금단 증상이 그릇을 괴롭힙니다.\u001FWithdrawal torments the vessel.").P(PersonalStatId.Health, -4).P(PersonalStatId.Mentality, -3)).With(PersonalStatId.Mentality),
                new Choice("쾌락에 기적을 섞는다\u001FMix miracles into pleasure", 0.90f, new Outcome("신성이 섞인 쾌락이 그릇 깊숙이 스며듭니다.\u001FPleasure laced with divinity seeps deep into the vessel.").P(PersonalStatId.Health, 4).C(StatId.Communion, -1).P(PersonalStatId.Lust, 2),
                    new Outcome("기적만 소모됩니다.\u001FIt only drains your Miracle.").C(StatId.Communion, -1)).With(PersonalStatId.Mentality))),
