                new Choice("대신 손을 얹어 기도한다\u001FLay on hands and pray instead", 0.90f, new Outcome("손을 얹자 병자의 숨이 편안해집니다.\u001FAt your touch, the sick man breathes easier.").C(StatId.FollowerFaith, 10).C(StatId.Communion, -1),
