        CultEvent.Random("vs27", StatId.Communion, new Question("숙주의 몸에서 다른 이의 상처를 대신 짊어지는 힘이 깨어났습니다. 신도의 멍이 당신의 팔에 옮겨 옵니다.\u001FA power to take on others' wounds has awakened in the host's body. A follower's bruise moves onto your arm.",
