        CultEvent.Random("vs29", StatId.Communion, new Question("숙주의 몸이 밤새 뜨겁게 타올라 침대 시트가 그을렸습니다. 신의 힘이 그릇을 넘쳐흐릅니다.\u001FThe host's body burned so hot all night that the bedsheets are scorched. The god's power is overflowing the vessel.",
