        CultEvent.Random("dl18", StatId.Followers, new Question("대학 동아리가 교단 체험을 신청했습니다. 젊은 학생들이 호기심 어린 눈으로 신전을 둘러봅니다.\u001FA university club has signed up to experience the cult. Young students look around the temple with curious eyes.",
