        CultEvent.Random("dl19", StatId.Doctrine, new Question("교리 강론회에서 신도가 쾌락과 신성의 경계가 어디냐고 묻습니다. 강론장이 조용해집니다.\u001FAt a doctrine lecture, a follower asks where the line lies between pleasure and the divine. The hall falls silent.",
