        CultEvent.Random("dl20", StatId.Authority, new Question("측근들이 당신의 행차 때 꽃잎을 뿌리자고 합니다. 바구니마다 장미 꽃잎이 가득합니다.\u001FYour inner circle wants to scatter petals when you go out in procession. Every basket is full of rose petals.",
