        CultEvent.Random("dl22", StatId.LeaderFaith, new Question("승천의 고리 한가운데가 꿈에 선명하게 보입니다. 아직 닿지 못한 빛이 손짓합니다.\u001FThe center of the ring of ascension appears vividly in your dream. A light you have yet to reach beckons.",
